mapper.select:
SELECT FROM post p JOIN member m ON p.member_id = m.id JOIN common_code c ON p.category_id = c.id WHERE p.subscriber_only = FALSE
AND p.category_id = #{categoryId}
AND p.id < #{cursor}
ORDER BY p.id DESC LIMIT #{size}

SELECT FROM post p INNER JOIN subscription s ON s.target_id = p.member_id JOIN member m ON p.member_id = m.id JOIN common_code c ON p.category_id = c.id JOIN common_code ss ON s.status_id = ss.id WHERE s.member_id = #{memberId} AND ss.type = 4 AND ss.code = 'SS01' AND p.subscriber_only = TRUE
AND p.category_id = #{categoryId}
AND p.id < #{cursor}
ORDER BY p.id DESC LIMIT #{size}

mapper.update:
UPDATE post
SET category_id = #{categoryId}, content = #{content}, image_url = #{imageUrl}, subscriber_only = #{subscriberOnly}
WHERE id = #{id}

UPDATE post
SET like_count = like_count + 1
WHERE id = #{postId}

UPDATE post
SET like_count = GREATEST(like_count - 1, 0)
WHERE id = #{postId}

UPDATE post
SET view_count = view_count + 1
WHERE id =  #{postId}

UPDATE post
SET reply_count = reply_count + 1
WHERE id = #{postId}

UPDATE post
SET reply_count = GREATEST(reply_count - 1, 0)
WHERE id = #{postId}

