SELECT FROM post p JOIN member m ON p.member_id = m.id JOIN common_code c ON p.category_id = c.id
AND content LIKE CONCAT('%', #{keyword}, '%')
AND member_id IN
#{targetId}
AND p.id < #{cursor}
AND p.subscriber_only = FALSE
AND(p.subscriber_only= FALSE OR p.member_id = #{memberId} OR EXISTS(SELECT 1 FROM subscription s JOIN common_code ss ON s.status_id = ss.id
WHERE s.member_id = #{memberId} AND s.target_id = p.member_id AND ss.type = 4 AND ss.code = 'SS01'))
ORDER BY id DESC LIMIT #{size}
